using Marina.Application.Abstractions; using Marina.Domain.Catalog; using Marina.Persistence.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using SixLabors.ImageSharp;
namespace Marina.Api.Controllers;
[ApiController,Authorize(Policy="StaffMfa"),Authorize(Policy="Products.Edit"),Route("api/v1/admin/media")]
public sealed class MediaController(IEnumerable<IMediaStorage>storageProviders,MarinaDbContext db):ControllerBase{private static readonly Dictionary<string,byte[]>Signatures=new(StringComparer.OrdinalIgnoreCase){{"image/jpeg",[0xFF,0xD8,0xFF]},{"image/png",[0x89,0x50,0x4E,0x47]},{"image/webp",[0x52,0x49,0x46,0x46]}};
 [HttpPost("products/{productId:guid}"),RequestSizeLimit(8*1024*1024)]public async Task<ActionResult>Upload(Guid productId,IFormFile file,CancellationToken ct){if(file.Length is<=0 or>8*1024*1024||!Signatures.TryGetValue(file.ContentType,out var signature))return BadRequest(new{message="Only JPEG, PNG, or WebP images up to 8 MB are accepted."});if(!await db.Products.AnyAsync(x=>x.Id==productId&&!x.IsDeleted,ct))return NotFound();if(await db.ProductImages.CountAsync(x=>x.ProductId==productId,ct)>=12)return Conflict(new{message="A product can have at most 12 images."});await using var input=file.OpenReadStream();var header=new byte[Math.Max(12,signature.Length)];var read=await input.ReadAsync(header,ct);input.Position=0;if(read<signature.Length||!header.AsSpan(0,signature.Length).SequenceEqual(signature))return BadRequest(new{message="File signature does not match the declared image type."});if(file.ContentType.Equals("image/webp",StringComparison.OrdinalIgnoreCase)&&(read<12||!header.AsSpan(8,4).SequenceEqual("WEBP"u8)))return BadRequest(new{message="Invalid WebP signature."});ImageInfo? info;try{info=await Image.IdentifyAsync(input,ct);}catch(UnknownImageFormatException){return BadRequest(new{message="Malformed or unsupported image."});}catch(InvalidImageContentException){return BadRequest(new{message="Malformed image content."});}if(info is null||info.Width>8000||info.Height>8000||(long)info.Width*info.Height>40_000_000)return BadRequest(new{message="Image dimensions exceed the safe limit."});input.Position=0;var storage=storageProviders.SingleOrDefault();if(storage is null)return StatusCode(503,new ProblemDetails{Status=503,Title="Media storage is not configured."});var extension=file.ContentType switch{"image/jpeg"=>".jpg","image/png"=>".png",_=>".webp"};var stored=await storage.StoreAsync(input,file.ContentType,$"{Guid.NewGuid():N}{extension}",ct);var sortOrder=await db.ProductImages.Where(x=>x.ProductId==productId).Select(x=>(int?)x.SortOrder).MaxAsync(ct)??-1;var image=new ProductImage{ProductId=productId,StorageKey=stored.StorageKey,Url=stored.PublicUrl,AltText="MARINA product image",SortOrder=sortOrder+1};db.ProductImages.Add(image);await db.SaveChangesAsync(ct);return Created("",new{image.Id,image.Url,image.SortOrder});}}
